function merge(file, ns) {
  const dict = JSON.parse(fs.readFileSync(file, "utf8"));
  dict.meta = Object.assign(dict.meta || {}, ns);
  fs.writeFileSync(file, JSON.stringify(dict, null, 2) + "\n");
  console.log("fusionné :", file);
}
merge("messages/fr.json", metaFr);
merge("messages/en.json", metaEn);
for (const [p, b64] of Object.entries(pages)) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, Buffer.from(b64, "base64").toString("utf8"));
  console.log("écrit    :", p);
}
const homePath = "app/[locale]/page.tsx";
if (fs.existsSync(homePath)) {
  let h = fs.readFileSync(homePath, "utf8");
  let n = 0;
  for (const [from, to] of homeReplacements) {
    if (to.includes("const fmtDate") && h.includes("const fmtDate")) continue;
    if (h.includes(from)) { h = h.replace(from, to); n++; }
  }
  fs.writeFileSync(homePath, h);
  console.log("accueil patché (" + n + "/" + homeReplacements.length + " patchs appliqués)");
}
